string CBoletaMaster::GetDayShiftName(int shift)
{
   if(shift == 0) return "Hoje (D0)";
   if(shift == 1) return "Ontem (D1)";
   return StringFormat("D-%d", shift);
}

void CBoletaMaster::AdjustDayShift(int delta)
{
   m_auto_day_shift += delta;
   if(m_auto_day_shift < 0)  m_auto_day_shift = 0;
   if(m_auto_day_shift > 30) m_auto_day_shift = 30;

   ObjectSetString(m_chart_id, PREFIX_GUI + "Btn_Chan_Day", OBJPROP_TEXT, GetDayShiftName(m_auto_day_shift));
   if(m_has_projections)
      ProjetarCanaisAuto();
   else
      ChartRedraw(m_chart_id);
}

void CBoletaMaster::ToggleDayShift()
{
   if(m_auto_day_shift == 0)      m_auto_day_shift = 1;
   else if(m_auto_day_shift == 1) m_auto_day_shift = 2;
   else                           m_auto_day_shift = 0;

   ObjectSetString(m_chart_id, PREFIX_GUI + "Btn_Chan_Day", OBJPROP_TEXT, GetDayShiftName(m_auto_day_shift));
   if(m_has_projections)
      ProjetarCanaisAuto();
   else
      ChartRedraw(m_chart_id);
}

void CBoletaMaster::ToggleChannelMeasureMode()
{
   m_auto_use_fixed_pts = !m_auto_use_fixed_pts;
   string mode_txt = m_auto_use_fixed_pts ? "Fixo (Pts)" : "Corpo (Sem Pavil)";
   color mode_bg   = m_auto_use_fixed_pts ? C'35,60,90' : C'25,95,65';
   ObjectSetString(m_chart_id, PREFIX_GUI + "Btn_Chan_Mode", OBJPROP_TEXT, mode_txt);
   ObjectSetInteger(m_chart_id, PREFIX_GUI + "Btn_Chan_Mode", OBJPROP_BGCOLOR, mode_bg);
   if(m_has_projections)
      ProjetarCanaisAuto();
   else
      ChartRedraw(m_chart_id);
}"

