   double amplitude   = 0.0;
   double topPrice    = 0.0;
   double bottomPrice = 0.0;

   if(!m_auto_use_fixed_pts || m_channel_pts <= 0)
   {
      // MODO PADRÃO: Pega estritamente o Topo e o Fundo do corpo do candle!
      topPrice    = body_top;
      bottomPrice = body_bottom;
      amplitude   = topPrice - bottomPrice;

      // Proteção para candle de abertura de hoje onde open == close
      if(amplitude <= (point * 2.0))
      {
         amplitude   = (m_channel_pts > 0 ? m_channel_pts : 500.0) * point;
         bottomPrice = topPrice - amplitude;
